        validator = ArtifactValidator()

        artifact = RawInterfaceArtifact(
            artifact_version="1.0.0",
            generation_timestamp="now",
            compilation_context=None,
            external_symbols=[],
            type_definitions={},
        )

        # Add a simple symbol
